package easy;import java.util.*;public class BinaryTreeTraversal{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static List<Integer>inorder(TreeNode n){List<Integer>r=new ArrayList<>();if(n!=null){inorder(r,n);}return r;}static void inorder(List<Integer>r,TreeNode n){if(n==null)return;inorder(r,n.l);r.add(n.val);inorder(r,n.r);}public static void main(String[]args){System.out.println("Traversal works");}}